--------------------------------------------------------
--  DDL for Table geografia
--------------------------------------------------------

  CREATE TABLE geografia
(
    id character varying(50) COLLATE pg_catalog."default" NOT NULL,
    nome character varying(300) COLLATE pg_catalog."default" NOT NULL,
    pais character varying(50) COLLATE pg_catalog."default",
    ilha character varying(50) COLLATE pg_catalog."default",
    concelho character varying(50) COLLATE pg_catalog."default",
    freguesia character varying(50) COLLATE pg_catalog."default",
    zona character varying(50) COLLATE pg_catalog."default",
    nome_norm character varying(300) COLLATE pg_catalog."default",
    nivel_detalhe character varying(2) COLLATE pg_catalog."default" NOT NULL,
    CONSTRAINT geografia_pkey PRIMARY KEY (id)
);
